import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, FlexProps, Switch, theme, Typography } from 'antd';

interface IOpenAllSwitchProps extends Omit<FlexProps, 'children'> {
	allIsOpened: boolean;
	setAllIsOpened: (value: boolean) => void;
	storageKey?: string;
}

export const OpenAllSwitch: FC<IOpenAllSwitchProps> = ({
	allIsOpened,
	setAllIsOpened,
	storageKey = 'allIsOpened',
	...props
}) => {
	const { t } = useTranslation();
	const {
		token: { colorTextSecondary },
	} = theme.useToken();

	return (
		<Flex {...props} gap={12} align="center">
			<Typography.Text style={{ color: colorTextSecondary }}>{t('Раскрыть все')}</Typography.Text>
			<Switch
				value={allIsOpened}
				onChange={(value) => {
					value && localStorage.setItem(storageKey, String(value));
					!value && localStorage.removeItem(storageKey);
					setAllIsOpened(value);
				}}
			/>
		</Flex>
	);
};
