import { FC, HTMLAttributes, ReactNode } from 'react';

import { Flex, Typography } from 'antd';

interface IListTopbarProps extends HTMLAttributes<HTMLDivElement> {
	leftComponent: ReactNode;
	rightComponent?: ReactNode;
	rightText?: string;
	rightData?: string | number;
}

export const ListTopbar: FC<IListTopbarProps> = ({
	className,
	leftComponent,
	rightComponent,
	rightData,
	rightText,
	...props
}) => {
	return (
		<Flex {...props} align="center" justify="space-between" className={className}>
			{leftComponent}
			{rightComponent}
			{rightText && (
				<Typography.Text type={'secondary'}>
					{rightText}: {rightData}
				</Typography.Text>
			)}
		</Flex>
	);
};
