import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, theme, Typography } from 'antd';
import { Flex } from 'antd';
import cn from 'classnames';

import CloseIcon from 'assets/images/icons/close.svg?react';

import styles from './CatalogBanner.module.scss';

interface ICatalogBannerProps extends HTMLAttributes<HTMLDivElement> {}

export const CatalogBanner: FC<ICatalogBannerProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const {
		token: { colorInfoBg, colorTextTertiary },
	} = theme.useToken();

	const [isClosed, setIsClosed] = useState(localStorage.getItem('catalogBannerClosed') === 'true');

	if (isClosed) return null;

	return (
		<div {...props} className={cn(className, styles.banner)} style={{ backgroundColor: colorInfoBg }}>
			<Flex vertical gap={4} className={styles.content}>
				<Typography.Title level={4} style={{ margin: 0 }}>
					{t('Кросс-конверсии теперь доступны для всех офферов по умолчанию!')}
				</Typography.Title>
				<Typography.Text type="secondary">
					{t('Выполнив несколько целевых действий, можно получить двойное вознаграждение.')}
				</Typography.Text>
			</Flex>

			<Button
				className={styles.close}
				onClick={() => {
					localStorage.setItem('catalogBannerClosed', 'true');
					setIsClosed(true);
				}}
				type="text"
				size="small"
				style={{ width: 28, height: 28, color: colorTextTertiary }}
				icon={<CloseIcon />}
			/>
		</div>
	);
};
